#import <Foundation/Foundation.h>
#import <CoreAudio/CoreAudio.h>
#import <AudioToolbox/AudioToolbox.h>
#include <cmath>
#include <algorithm>
#include <vector>
#include <cstdio>
#include <unistd.h>
struct Tone {double rate=48000,frequency=997,amplitude=.001;uint64_t frame=0,total=48000;};
static OSStatus render(void*ctx,AudioUnitRenderActionFlags*,const AudioTimeStamp*,UInt32,UInt32 count,AudioBufferList*buffers){auto*t=(Tone*)ctx;for(UInt32 f=0;f<count;f++){double envelope=std::min(1.0,std::min((double)t->frame/(t->rate*.05),(double)(t->total>t->frame?t->total-t->frame:0)/(t->rate*.05)));float value=t->frame<t->total?t->amplitude*std::max(0.0,envelope)*sin(2*M_PI*t->frequency*t->frame/t->rate):0;for(UInt32 b=0;b<buffers->mNumberBuffers;b++){auto&buf=buffers->mBuffers[b];if(buf.mData&&((uint64_t)f*buf.mNumberChannels+buf.mNumberChannels)*sizeof(float)<=buf.mDataByteSize)for(UInt32 c=0;c<buf.mNumberChannels;c++)((float*)buf.mData)[f*buf.mNumberChannels+c]=value;}t->frame++;}return noErr;}
int main(int argc,char**argv){@autoreleasepool{if(argc<2){fprintf(stderr,"Usage: route-tone DEVICE_UID [frequency=997] [seconds=1] [amplitude=.001]\n");return 2;}NSString*uid=[NSString stringWithUTF8String:argv[1]];AudioDeviceID device=0;AudioObjectPropertyAddress a{kAudioHardwarePropertyDevices,kAudioObjectPropertyScopeGlobal,kAudioObjectPropertyElementMain};UInt32 size=0;OSStatus status=AudioObjectGetPropertyDataSize(kAudioObjectSystemObject,&a,0,nullptr,&size);if(status)return 3;std::vector<AudioDeviceID>devices(size/sizeof(AudioDeviceID));status=AudioObjectGetPropertyData(kAudioObjectSystemObject,&a,0,nullptr,&size,devices.data());if(status)return 3;for(auto candidate:devices){CFStringRef candidateUID=nullptr;UInt32 bytes=sizeof(candidateUID);AudioObjectPropertyAddress property{kAudioDevicePropertyDeviceUID,kAudioObjectPropertyScopeGlobal,kAudioObjectPropertyElementMain};if(AudioObjectGetPropertyData(candidate,&property,0,nullptr,&bytes,&candidateUID)==noErr&&candidateUID){bool matches=[(__bridge NSString*)candidateUID isEqualToString:uid];CFRelease(candidateUID);if(matches){device=candidate;break;}}}if(!device){fprintf(stderr,"Output UID unavailable: %s\n",argv[1]);return 3;}Tone t;t.frequency=argc>2?atof(argv[2]):997;double seconds=argc>3?atof(argv[3]):1;t.amplitude=argc>4?atof(argv[4]):.001;if(!std::isfinite(t.frequency)||t.frequency<20||t.frequency>18000||!std::isfinite(seconds)||seconds<=0||seconds>5||!std::isfinite(t.amplitude)||t.amplitude<0||t.amplitude>.0031623)return 4;a.mSelector=kAudioDevicePropertyNominalSampleRate;size=sizeof(t.rate);if(AudioObjectGetPropertyData(device,&a,0,nullptr,&size,&t.rate))return 5;t.total=t.rate*seconds;AudioComponentDescription desc{kAudioUnitType_Output,kAudioUnitSubType_HALOutput,kAudioUnitManufacturer_Apple,0,0};AudioComponent component=AudioComponentFindNext(nullptr,&desc);AudioUnit unit=nullptr;if(!component||AudioComponentInstanceNew(component,&unit))return 6;
status=AudioUnitSetProperty(unit,kAudioOutputUnitProperty_CurrentDevice,kAudioUnitScope_Global,0,&device,sizeof(device));AudioStreamBasicDescription format{t.rate,kAudioFormatLinearPCM,kAudioFormatFlagIsFloat|kAudioFormatFlagIsPacked,8,1,8,2,32,0};if(!status)status=AudioUnitSetProperty(unit,kAudioUnitProperty_StreamFormat,kAudioUnitScope_Input,0,&format,sizeof(format));AURenderCallbackStruct callback{render,&t};if(!status)status=AudioUnitSetProperty(unit,kAudioUnitProperty_SetRenderCallback,kAudioUnitScope_Input,0,&callback,sizeof(callback));if(!status)status=AudioUnitInitialize(unit);if(!status)status=AudioOutputUnitStart(unit);if(!status)usleep((useconds_t)((seconds+.1)*1000000));AudioOutputUnitStop(unit);AudioUnitUninitialize(unit);AudioComponentInstanceDispose(unit);if(status)fprintf(stderr,"tone output error %d\n",status);if(!status&&t.frame==0){fprintf(stderr,"Output started but render callback received no frames.\n");return 8;}return status?7:0;}}
